package com.grdp.studio.wellbore.temperature.entity;
import com.baomidou.mybatisplus.annotation.*;
@TableName("project_well_temperature_profile") public class TemperatureProfileEntity { @TableId(type=IdType.AUTO) private Long id; private Long temperatureId; private Integer pointNo; private Double depthM,fluidTemperatureC,formationTemperatureC; public Long getId(){return id;} public void setId(Long v){id=v;} public Long getTemperatureId(){return temperatureId;} public void setTemperatureId(Long v){temperatureId=v;} public Integer getPointNo(){return pointNo;} public void setPointNo(Integer v){pointNo=v;} public Double getDepthM(){return depthM;} public void setDepthM(Double v){depthM=v;} public Double getFluidTemperatureC(){return fluidTemperatureC;} public void setFluidTemperatureC(Double v){fluidTemperatureC=v;} public Double getFormationTemperatureC(){return formationTemperatureC;} public void setFormationTemperatureC(Double v){formationTemperatureC=v;} }
